function(row){
  var c = (row.Country || '').toString().trim();
  // collapse internal whitespace
  c = c.replace(/\s+/g, ' ');
  var key = c.toLowerCase().replace(/[.]/g,'');
  var map = {
    'us':'United States','usa':'United States','u s a':'United States',
    'united states':'United States','united states of america':'United States',
    'america':'United States',
    'uk':'United Kingdom','u k':'United Kingdom','united kingdom':'United Kingdom',
    'britain':'United Kingdom','great britain':'United Kingdom','england':'United Kingdom',
    'uae':'United Arab Emirates','united arab emirates':'United Arab Emirates',
    'south korea':'South Korea','korea south':'South Korea','republic of korea':'South Korea',
    'north korea':'North Korea',
    'russia':'Russia','russian federation':'Russia',
    'czech republic':'Czech Republic','czechia':'Czech Republic',
    'holland':'Netherlands','netherlands':'Netherlands','the netherlands':'Netherlands',
    'ivory coast':"Cote d'Ivoire","cote d'ivoire":"Cote d'Ivoire",
    'vietnam':'Vietnam','viet nam':'Vietnam'
  };
  if (map.hasOwnProperty(key)) return map[key];
  // default: title case each word
  return c.split(' ').map(function(w){
    if (w.length === 0) return w;
    return w.charAt(0).toUpperCase() + w.slice(1).toLowerCase();
  }).join(' ');
}

function pad(n){return String(n).padStart(2,'0');}
let raw = row.DOB;
if (raw == null || raw === '') return raw;
let s = String(raw).trim();
let m;
if (m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/)) {
  return `${m[1]}-${pad(m[2])}-${pad(m[3])}`;
}
if (m = s.match(/^(\d{4})\/(\d{1,2})\/(\d{1,2})$/)) {
  return `${m[1]}-${pad(m[2])}-${pad(m[3])}`;
}
if (m = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/)) {
  let a=parseInt(m[1],10), b=parseInt(m[2],10), y=m[3];
  let month = a<=12 ? a : b;
  let day = a<=12 ? b : a;
  return `${y}-${pad(month)}-${pad(day)}`;
}
let d = new Date(s);
if (!isNaN(d.getTime())) {
  return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
}
return s;

